const foundationsPage = figma.root.children.find(p => p.id === "1:2");
const componentsPage = figma.root.children.find(p => p.id === "1:3");
const mediaPage = figma.root.children.find(p => p.id === "1:4");

const getChildrenRecursive = (node, depth = 0) => {
  if (depth > 3) return { id: node.id, name: node.name, type: node.type, message: "Depth limit reached" };
  const res = { id: node.id, name: node.name, type: node.type };
  if ("children" in node) {
    res.children = node.children.map(c => getChildrenRecursive(c, depth + 1));
  }
  return res;
};

const result = {
  foundations: foundationsPage.children.map(c => getChildrenRecursive(c)),
  components: componentsPage.children.map(c => getChildrenRecursive(c)),
  media: mediaPage.children.map(c => getChildrenRecursive(c))
};

return JSON.stringify(result, null, 2);

