const page = figma.root.children.find(p => p.id === "1:2");
const result = [];
const traverse = (node) => {
  result.push({ id: node.id, name: node.name, type: node.type, fills: node.fills, strokes: node.strokes, characters: node.characters });
  if ("children" in node) {
    node.children.forEach(traverse);
  }
};
page.children.forEach(traverse);
return JSON.stringify(result, null, 2);

const foundationsPage = figma.root.children.find(p => p.id === "1:2");
console.log("Foundations children count:", foundationsPage.children.length);
return JSON.stringify(foundationsPage.children.map(c => ({ id: c.id, name: c.name, type: c.type })), null, 2);

const page = figma.root.children.find(p => p.id === "1:3");
const components = page.children;
return JSON.stringify(components.map(c => ({
  id: c.id,
  name: c.name,
  type: c.type,
  x: c.x,
  y: c.y,
  width: c.width,
  height: c.height
})), null, 2);

const mainFrame = figma.getNodeById("1:19");
const subNodes = mainFrame.children;
return JSON.stringify(subNodes.map(c => ({
  id: c.id,
  name: c.name,
  type: c.type,
  x: c.x,
  y: c.y,
  width: c.width,
  height: c.height
})), null, 2);

const shellFrame = figma.getNodeById("1:32");
return JSON.stringify(shellFrame.children.map(c => ({
  id: c.id,
  name: c.name,
  type: c.type,
  x: c.x,
  y: c.y,
  width: c.width,
  height: c.height
})), null, 2);

const button = figma.getNodeById("1:23");
const textField = figma.getNodeById("1:26");
const statusBar = figma.getNodeById("1:33");
const homeIndicator = figma.getNodeById("1:44");

const getProperties = (node) => {
  return {
    id: node.id,
    name: node.name,
    type: node.type,
    width: node.width,
    height: node.height,
    fills: node.fills,
    strokes: node.strokes,
    cornerRadius: node.cornerRadius,
    topLeftRadius: node.topLeftRadius,
    topRightRadius: node.topRightRadius,
    bottomLeftRadius: node.bottomLeftRadius,
    bottomRightRadius: node.bottomRightRadius,
    effects: node.effects,
    layoutAlign: node.layoutAlign,
    layoutGrow: node.layoutGrow,
    primaryAxisSizingMode: node.primaryAxisSizingMode,
    counterAxisSizingMode: node.counterAxisSizingMode,
    paddingLeft: node.paddingLeft,
    paddingRight: node.paddingRight,
    paddingTop: node.paddingTop,
    paddingBottom: node.paddingBottom,
    itemSpacing: node.itemSpacing,
    layoutMode: node.layoutMode
  };
};

return JSON.stringify({
  button: getProperties(button),
  textField: getProperties(textField),
  statusBar: getProperties(statusBar),
  homeIndicator: getProperties(homeIndicator)
}, null, 2);

const btn = figma.getNodeById("1:23");
const txtField = figma.getNodeById("1:26");

const getChildrenProps = (node) => {
  const props = { id: node.id, name: node.name, type: node.type, fills: node.fills, strokes: node.strokes, cornerRadius: node.cornerRadius, width: node.width, height: node.height };
  if (node.type === "TEXT") {
    props.characters = node.characters;
    props.fontSize = node.fontSize;
    props.fontName = node.fontName;
    props.textColor = node.fills;
  }
  if ("children" in node) {
    props.children = node.children.map(getChildrenProps);
  }
  return props;
};

return JSON.stringify({
  buttonChildren: btn.children.map(getChildrenProps),
  textFieldChildren: txtField.children.map(getChildrenProps)
}, null, 2);

