  windingRule: "EVENODD",
  data: "M 0 60 C 30 50, 50 30, 80 40 C 110 50, 140 80, 170 60 C 200 40, 220 10, 250 20 C 280 30, 300 50, 334 10"
}];
curve.resize(334, 60);
curve.x = 0;
curve.y = 15;
