const xStep = 334 / 4;
hours.forEach((h, idx) => {
  const isSelected = h === "4PM";
  const lbl = createText(h, 11, isSelected ? "Bold" : "Medium", isSelected ? BRAND_PRIMARY : TEXT_MUTED);
  lbl.textAlignHorizontal = "CENTER";
  lbl.resize(40, 16);
  lbl.x = idx * xStep - 20;
  if (idx === 0) lbl.x = 0;
  if (idx === 4) lbl.x = 334 - 40;
  lbl.y = 90;
  chartContainer.appendChild(lbl);
});

